Demo 2 clarifies the rule: each scattered marker cell gets a copy of the object stamped centered on it (object's bounding-box center aligned to the marker), original kept.

```python
def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    # find largest connected component of non-bg cells = object
    seen = [[False]*w for _ in range(h)]
    best = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] != bg and not seen[i][j]:
                comp = []
                stack = [(i, j)]
                seen[i][j] = True
                while stack:
                    r, c = stack.pop()
                    comp.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != bg:
                                seen[nr][nc] = True
                                stack.append((nr, nc))
                if len(comp) > len(best):
                    best = comp
    obj = set(best)
    minr = min(r for r, c in obj); maxr = max(r for r, c in obj)
    minc = min(c for r, c in obj); maxc = max(c for r, c in obj)
    cr = (minr + maxr) // 2
    cc = (minc + maxc) // 2
    pattern = {(r-cr, c-cc): grid[r][c] for r, c in obj}
    # marker cells: non-bg cells not in object
    markers = [(i, j) for i in range(h) for j in range(w)
               if grid[i][j] != bg and (i, j) not in obj]
    out = [row[:] for row in grid]
    for r, c in markers:
        for (dr, dc), v in pattern.items():
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                out[nr][nc] = v
    return out
